#pragma once
#include "Processor.h"
#include "GlassStyle.h"
class ReferenceView final:public juce::Component,private juce::ScrollBar::Listener {
    NovaProcessor& p;std::shared_ptr<const ReferenceFile> file;
    juce::TextButton autoFit{"Recrear seleccion"};juce::TextEditor beginField,endField;juce::TextButton zoomIn{"Lupa +"},zoomOut{"Lupa -"},whole{"Ver todo"},detail{"Ver seleccion"},play{"Escuchar"};juce::ToggleButton autoNote{"Auto nota"},cleanNote{"Tono limpio"},context{"Contexto / instrumento"};juce::ScrollBar scroll{false};
    bool guided=false;juce::TextButton chooseAudio{"Cargar audio"},continueButton{"Revisar fragmento"},options{"Opciones de seleccion"};
    double viewStart=0,viewLength=1,anchor=0;int dragMode=0;bool dragged=false;
    juce::Rectangle<float> waveArea()const{return {12,35,getWidth()-24.f,std::max(80.f,getHeight()-120.f)};}
    float xAt(double t)const{return waveArea().getX()+static_cast<float>((t-viewStart)/viewLength)*waveArea().getWidth();}
    double timeAt(float x)const{return std::clamp(viewStart+(x-waveArea().getX())/waveArea().getWidth()*viewLength,0.,file?file->duration:0.);}
    void view(double start,double length){if(!file)return;viewLength=std::clamp(length,std::min(.05,file->duration),file->duration);viewStart=std::clamp(start,0.,std::max(0.,file->duration-viewLength));scroll.setRangeLimits(0,file->duration);scroll.setCurrentRange(viewStart,viewLength,juce::dontSendNotification);repaint();}
    void zoom(double factor){if(!file)return;double centre=viewStart+viewLength*.5;view(centre-viewLength*factor*.5,viewLength*factor);}
    void commit(){if(!file||beginField.getText().isEmpty()||endField.getText().isEmpty())return;try{size_t a=0,b=0;auto textA=beginField.getText().toStdString(),textB=endField.getText().toStdString();double start=std::stod(textA,&a),end=std::stod(textB,&b);if(a!=textA.size()||b!=textB.size()||!std::isfinite(start)||!std::isfinite(end))throw std::invalid_argument("time");p.selectRange(nova::SelectionRange::between(start,end,file->duration,p.selectionMaximum()));refresh();}catch(...){p.say("Introduce tiempos validos en segundos, por ejemplo 25.500.");}}
    void scrollBarMoved(juce::ScrollBar*,double start)override{viewStart=start;repaint();}
    static juce::String timeText(double t){int minutes=static_cast<int>(t)/60;return juce::String(minutes)+":"+juce::String(t-minutes*60,3).paddedLeft('0',6);}
public:
    juce::Colour accent{0xff40a9ff};std::function<void()> onChoose,onNext;
    void setGuided(){guided=true;for(auto* c:std::initializer_list<juce::Component*>{&chooseAudio,&continueButton,&options}){addAndMakeVisible(c);c->setWantsKeyboardFocus(false);}chooseAudio.onClick=[this]{if(onChoose)onChoose();};continueButton.onClick=[this]{if(onNext)onNext();};options.onClick=[this]{p.uiReferenceOptions.store(!p.uiReferenceOptions.load());resized();repaint();};resized();}

    explicit ReferenceView(NovaProcessor& owner):p(owner){
        for(auto* c:std::initializer_list<juce::Component*>{&autoFit,&beginField,&endField,&zoomIn,&zoomOut,&whole,&detail,&play,&autoNote,&cleanNote,&context,&scroll})addAndMakeVisible(c);
        for(auto* field:{&beginField,&endField}){field->setInputRestrictions(12,"0123456789.");field->setSelectAllWhenFocused(true);field->onReturnKey=[this]{commit();};field->onFocusLost=[this]{commit();};field->setColour(juce::TextEditor::backgroundColourId,juce::Colour(0x60202a3b));field->setColour(juce::TextEditor::textColourId,juce::Colours::white);}
        for(auto* b:std::initializer_list<juce::Component*>{&zoomIn,&zoomOut,&whole,&detail,&play,&autoNote,&cleanNote,&context,&scroll})b->setWantsKeyboardFocus(false);
        autoFit.onClick=[this]{p.startFit();};autoFit.setWantsKeyboardFocus(false);autoFit.setTooltip("Nota corta: busca entre cinco motores. Contexto largo: aprende automaticamente. Para elegir notas antes de aprender usa Aprender.");
        play.onClick=[this]{if(auto* editor=findParentComponentOfClass<juce::AudioProcessorEditor>())editor->grabKeyboardFocus();p.toggleReference();};play.setTooltip("Escuchar / detener el fragmento original seleccionado. Espacio en MUESTRA.");
        zoomIn.onClick=[this]{zoom(.5);};zoomOut.onClick=[this]{zoom(2);};whole.onClick=[this]{if(file)view(0,file->duration);};detail.onClick=[this]{auto r=p.selectedRange();view(r.start-r.length()*.12,r.length()*1.24);};autoNote.onClick=[this]{p.autoPitch.store(autoNote.getToggleState());};cleanNote.onClick=[this]{p.cleanPitch.store(cleanNote.getToggleState());};cleanNote.setTooltip("En la proxima recreacion estabiliza los armonicos de sonidos tonales. Campanas y sonidos inarmonicos se conservan.");context.onClick=[this]{p.setContextEnabled(context.getToggleState());refresh();};context.setTooltip("Hasta 60 segundos: analiza varias notas y aprende el instrumento para tocarlo desde MIDI/piano roll. No reproduce la frase completa.");scroll.addListener(this);
    }
    ~ReferenceView()override{scroll.removeListener(this);beginField.onFocusLost=nullptr;endField.onFocusLost=nullptr;}
    void refresh(){autoFit.setButtonText(p.contextEnabled.load()&&p.selectedRange().length()>3.0001?"Aprender contexto":"Recrear seleccion");beginField.setFont(juce::Font(14*p.textScale()));endField.setFont(juce::Font(14*p.textScale()));auto next=p.sourceView();if(next!=file){file=std::move(next);if(file)view(0,file->duration);}auto r=p.selectedRange();if(!beginField.hasKeyboardFocus(true))beginField.setText(juce::String(r.start,6),false);if(!endField.hasKeyboardFocus(true))endField.setText(juce::String(r.end,6),false);context.setToggleState(p.contextEnabled.load(),juce::dontSendNotification);cleanNote.setToggleState(p.cleanPitch.load(),juce::dontSendNotification);play.setButtonText(p.referencePlaying()?"Detener":"Escuchar");autoNote.setToggleState(p.autoPitch.load(),juce::dontSendNotification);for(auto* c:std::initializer_list<juce::Component*>{&autoFit,&beginField,&endField,&zoomIn,&zoomOut,&whole,&detail,&play,&autoNote,&cleanNote,&context,&scroll})c->setEnabled(file!=nullptr);if(guided){continueButton.setEnabled(file!=nullptr);resized();}repaint();}
    void resized()override{autoFit.setBounds(getWidth()-190,4,178,26);int delta=getHeight()-252;scroll.setBounds(12,170+delta,getWidth()-24,16);beginField.setBounds(62,205+delta,105,26);endField.setBounds(210,205+delta,105,26);zoomIn.setBounds(325,205+delta,65,26);zoomOut.setBounds(394,205+delta,65,26);whole.setBounds(464,205+delta,78,26);detail.setBounds(546,205+delta,120,26);autoNote.setBounds(673,205+delta,105,26);play.setBounds(788,205+delta,112,26);cleanNote.setBounds(12,232+delta,140,20);context.setBounds(158,232+delta,210,20);if(guided){bool expanded=p.uiReferenceOptions.load();autoFit.setVisible(expanded);autoNote.setVisible(expanded);cleanNote.setVisible(expanded);context.setVisible(expanded);options.setBounds(getWidth()-226,getHeight()-22,214,20);options.setToggleState(expanded,juce::dontSendNotification);continueButton.setBounds(getWidth()-216,4,204,26);chooseAudio.setBounds(file?getWidth()-370:(getWidth()-280)/2,file?4:getHeight()/2-20,file?144:280,file?26:42);options.setVisible(file!=nullptr);continueButton.setVisible(file!=nullptr);autoFit.setBounds(385,getHeight()-22,178,20);autoNote.setBounds(570,getHeight()-22,112,20);}
}
    void paint(juce::Graphics& g)override{
        nova::glass::panel(g,getLocalBounds().toFloat(),accent,18,this);g.setFont(13.f*p.textScale());g.setColour(juce::Colour(0xffcccccc));
        if(!file){g.drawText(p.loading.load()?"Leyendo la forma de onda... puedes cancelar desde el boton superior.":"Arrastra un audio aqui o pulsa Cargar audio.",getLocalBounds(),juce::Justification::centred);return;}
        int delta=getHeight()-252;auto area=waveArea();g.drawText(file->file.getFileName()+" / "+timeText(file->duration)+" / arrastra para seleccionar; bordes: ajustar; Shift: mover",12,4,getWidth()-224,25,juce::Justification::centredLeft);
        g.setColour(juce::Colour(0xff0a1019).withAlpha(.78f));g.fillRect(area);auto r=p.selectedRange();
        {juce::Graphics::ScopedSaveState state(g);g.reduceClipRegion(area.toNearestInt());g.setColour(juce::Colour(0xff777777));
        const auto* peaks=&file->peaks;double stride=nova::PeakBuilder::stride;for(const auto& level:file->mips){if(viewLength*file->rate/stride<=area.getWidth()*4)break;peaks=&level;stride*=8;}
        for(int x=0;x<static_cast<int>(area.getWidth());++x){double a=viewStart+x/area.getWidth()*viewLength,b=viewStart+(x+1)/area.getWidth()*viewLength;size_t first=std::min(peaks->size(),static_cast<size_t>(a*file->rate/stride)),last=std::min(peaks->size(),static_cast<size_t>(b*file->rate/stride)+1);float lo=0,hi=0;for(size_t k=first;k<last;++k){lo=std::min(lo,(*peaks)[k].low);hi=std::max(hi,(*peaks)[k].high);}float scale=area.getHeight()*.46f;g.drawVerticalLine(static_cast<int>(area.getX())+x,area.getCentreY()-std::min(1.f,hi)*scale,area.getCentreY()-std::max(-1.f,lo)*scale);}
        for(const auto& note:p.learnedContextNotes()){float a=xAt(note.range.start),b=xAt(note.range.end);g.setColour(accent.withAlpha(.35f));g.fillRect(a,area.getBottom()-16,std::max(2.f,b-a),16.f);g.setColour(juce::Colours::white);g.setFont(11.f*p.textScale());g.drawText("MIDI "+juce::String(note.note),static_cast<int>(a)+2,static_cast<int>(area.getBottom())-16,std::max(20,static_cast<int>(b-a)-4),16,juce::Justification::centredLeft);}float left=xAt(r.start),right=xAt(r.end);g.setColour(accent.withAlpha(.23f));g.fillRect(left,area.getY(),std::max(2.f,right-left),area.getHeight());juce::Path edges;edges.startNewSubPath(left,area.getY());edges.lineTo(left,area.getBottom());edges.startNewSubPath(right,area.getY());edges.lineTo(right,area.getBottom());nova::glass::strokeGlow(g,edges,accent,2.f);double pos=p.referencePosition();if(pos>=0){g.setColour(juce::Colours::white);g.drawVerticalLine(static_cast<int>(xAt(pos)),area.getY(),area.getBottom());}}
        g.setFont(11.f*p.textScale());g.setColour(juce::Colour(0xffaaaaaa));g.drawText(timeText(viewStart),12,187+delta,150,15,juce::Justification::centredLeft);g.drawText(timeText(viewStart+viewLength),getWidth()-162,187+delta,150,15,juce::Justification::centredRight);
        g.setFont(12.f*p.textScale());g.drawText("Inicio s",12,205+delta,48,26,juce::Justification::centredLeft);g.drawText("Fin s",177,205+delta,32,26,juce::Justification::centredLeft);g.setColour(accent);g.drawText(juce::String(r.length(),3)+" s / max. "+juce::String(static_cast<int>(p.selectionMaximum()))+" s",910,205+delta,getWidth()-922,26,juce::Justification::centredRight);g.setColour(juce::Colour(0xff999999));if(!guided)g.drawText(p.contextEnabled.load()?"Contexto largo: aprende notas e intensidades. Espacio: escuchar seleccion.":"Nota aislada: hasta 3 s. Espacio: escuchar. Doble clic: ampliar seleccion.",375,234+delta,getWidth()-387,16,juce::Justification::centredLeft);
    }
    void mouseDown(const juce::MouseEvent& e)override{if(!file||!waveArea().contains(e.position))return;if(auto* editor=findParentComponentOfClass<juce::AudioProcessorEditor>())editor->grabKeyboardFocus();auto r=p.selectedRange();anchor=timeAt(e.position.x);dragged=false;bool wide=xAt(r.end)-xAt(r.start)>14;dragMode=e.mods.isShiftDown()?3:wide&&std::abs(e.position.x-xAt(r.start))<8?1:wide&&std::abs(e.position.x-xAt(r.end))<8?2:anchor>=r.start&&anchor<=r.end?3:4;if(dragMode==4){auto next=r;next.move(anchor,file->duration,p.selectionMaximum());p.selectRange(next);}if(dragMode==3)anchor-=r.start;refresh();}
    void mouseDrag(const juce::MouseEvent& e)override{if(!file||!dragMode)return;dragged=true;auto r=p.selectedRange();double t=timeAt(e.position.x);if(dragMode==1)r.resizeStart(t,file->duration,p.selectionMaximum());if(dragMode==2)r.resizeEnd(t,file->duration,p.selectionMaximum());if(dragMode==3)r.move(t-anchor,file->duration,p.selectionMaximum());if(dragMode==4)r=nova::SelectionRange::between(anchor,std::clamp(t,anchor-p.selectionMaximum(),anchor+p.selectionMaximum()),file->duration,p.selectionMaximum());p.selectRange(r);refresh();}
    void mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& wheel)override{if(file&&waveArea().contains(e.position)){double pivot=timeAt(e.position.x),factor=wheel.deltaY>0?.65:1.55;double fraction=(e.position.x-waveArea().getX())/waveArea().getWidth();double length=std::clamp(viewLength*factor,std::min(.05,file->duration),file->duration);view(pivot-length*fraction,length);}}
    void mouseUp(const juce::MouseEvent&)override{dragMode=0;}
    void mouseDoubleClick(const juce::MouseEvent& e)override{if(file&&waveArea().contains(e.position)){auto r=p.selectedRange();view(r.start-r.length()*.12,r.length()*1.24);}}
};
